import { expect, expectStatus, test } from "../../fixtures";

// QA lead, 2026-11-02: the vendor endpoint is being rewritten (PLAT-412), so this stays skipped until it lands.
test.fixme("A vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs, factory }) => {
  // Arrange: a member's vendor, submitted and awaiting review
  const member = await apiAs("member");
  const { vendor } = await factory.vendorInReview({ as: "member" });

  // Act: the member changes the vendor's contact email
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert: the edit is refused with vendor_locked, and the stored vendor is unchanged
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");
  const after = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(after.status).toBe("in_review");
  expect(after.contact_email).not.toBe("billing@acmefreight.example");
});
